using System;using System.Collections.Generic;namespace Microsoft.VisualStudio.Services.Identity{    /// <summary>    /// Provides a mapping between identity type names and their byte IDs for Azure DevOps/TFS identity systems.    /// </summary>    /// <remarks>    /// <para><strong>Why this exists:</strong></para>    /// <para>    /// The IdentityTypeMapper class was part of the Microsoft.VisualStudio.Services.Client SDK in versions prior    /// to v19. Starting with v19 of the Azure DevOps SDK (Microsoft.VisualStudio.Services.Client), Microsoft    /// removed this class from the public API. However, Qwiq and other libraries that work with TFS/Azure DevOps    /// identity systems still need to convert between identity type byte IDs and their string names.    /// </para>    /// <para>    /// This compatibility shim recreates the essential functionality that was lost when the SDK was updated,    /// allowing Qwiq to work with both old and new versions of the Azure DevOps SDK without breaking existing    /// functionality.    /// </para>    ///    /// <para><strong>What it does:</strong></para>    /// <para>    /// This class maintains a bidirectional mapping between:    /// <list type="bullet">    ///   <item><description>Identity type byte IDs (0-16) used internally by TFS/Azure DevOps</description></item>    ///   <item><description>Identity type names (e.g., "Microsoft.TeamFoundation.Identity") used in code</description></item>    /// </list>    /// </para>    ///    /// <para><strong>When it can be removed:</strong></para>    /// <para>    /// This class can be safely removed when:    /// <list type="number">    ///   <item><description>Qwiq no longer needs to support Azure DevOps SDK versions v19 or later, OR</description></item>    ///   <item><description>Microsoft restores the IdentityTypeMapper class to the public SDK API, OR</description></item>    ///   <item><description>All Qwiq functionality that depends on identity type mapping is refactored to use    ///     alternative approaches that don't require this mapping</description></item>    /// </list>    /// </para>    ///    /// <para><strong>Testing considerations:</strong></para>    /// <para>    /// Any tests that work with identity types should verify that:    /// <list type="bullet">    ///   <item><description>Known identity types map correctly in both directions</description></item>    ///   <item><description>Unknown identity types are handled gracefully (assigned a new ID dynamically)</description></item>    ///   <item><description>Thread safety is maintained for concurrent access (Lazy initialization)</description></item>    /// </list>    /// </para>    /// </remarks>    internal sealed class IdentityTypeMapper    {        private static readonly Lazy<IdentityTypeMapper> LazyInstance =            new Lazy<IdentityTypeMapper>(() => new IdentityTypeMapper());        /// <summary>        /// Gets the singleton instance of the IdentityTypeMapper.        /// </summary>        internal static IdentityTypeMapper Instance => LazyInstance.Value;        // Common identity types based on TFS/Azure DevOps identity system        // These mappings are based on the original Microsoft implementation        private readonly Dictionary<byte, string> _idToName = new Dictionary<byte, string>        {            { 0, "System.Security.Principal.WindowsIdentity" },            { 1, "Microsoft.TeamFoundation.Identity" },            { 2, "Microsoft.TeamFoundation.ServiceIdentity" },            { 3, "Microsoft.TeamFoundation.UnauthenticatedIdentity" },            { 4, "Microsoft.IdentityModel.Claims.ClaimsIdentity" },            { 5, "Microsoft.TeamFoundation.Framework.Server.TeamFoundationApplicationGroup" },            { 6, "Microsoft.TeamFoundation.GroupIdentity" },            { 7, "Microsoft.TeamFoundation.BindPendingIdentity" },            { 8, "Microsoft.TeamFoundation.ImportedIdentity" },            { 9, "Microsoft.TeamFoundation.AggregateIdentity" },            { 10, "Microsoft.TeamFoundation.ServerIdentity" },            { 11, "Microsoft.TeamFoundation.CertificateIdentity" },            { 12, "Microsoft.TeamFoundation.SystemIdentity" },            { 13, "Microsoft.TeamFoundation.ServicePrincipal" },            { 14, "Microsoft.VisualStudio.Services.Identity.AadUser" },            { 15, "Microsoft.VisualStudio.Services.Identity.MsaUser" },            { 16, "Microsoft.VisualStudio.Services.Identity.VssUser" },        };        private readonly Dictionary<string, byte> _nameToId = new Dictionary<string, byte>(StringComparer.OrdinalIgnoreCase);        private IdentityTypeMapper()        {            foreach (var kvp in _idToName)            {                _nameToId[kvp.Value] = kvp.Key;            }        }        /// <summary>        /// Gets the identity type name from its byte ID.        /// </summary>        /// <param name="typeId">The byte ID of the identity type.</param>        /// <returns>The identity type name, or a formatted string if unknown.</returns>        internal string GetTypeNameFromId(byte typeId)        {            if (_idToName.TryGetValue(typeId, out var name))            {                return name;            }            // For unknown types, return a placeholder            return $"UnknownIdentityType_{typeId}";        }        /// <summary>        /// Gets the byte ID for an identity type name.        /// </summary>        /// <param name="typeName">The identity type name.</param>        /// <returns>The byte ID of the identity type.</returns>        /// <exception cref="ArgumentException">Thrown when the type name is not recognized.</exception>        internal byte GetTypeIdFromName(string typeName)        {            if (string.IsNullOrEmpty(typeName))            {                throw new ArgumentNullException(nameof(typeName));            }            if (_nameToId.TryGetValue(typeName, out var id))            {                return id;            }            // Try to register unknown types dynamically            // Find the next available ID            byte nextId = (byte)(_idToName.Count);            while (_idToName.ContainsKey(nextId) && nextId < byte.MaxValue)            {                nextId++;            }            if (nextId == byte.MaxValue && _idToName.ContainsKey(nextId))            {                throw new InvalidOperationException("Maximum number of identity types exceeded.");            }            // Register the new type            _idToName[nextId] = typeName;            _nameToId[typeName] = nextId;            return nextId;        }    }}